"""C09 (JRD1 attack (i) for C8; DR-4 AC-12 mutation in the F-10 shape; D-7).

AC-12 as the revision words it: "AST scan of r1 for random.Random constructions and
module-level random calls; every construction takes count_roots's rng_seed (r1/indep) or a
seeds.py stream (r1/runner)"; fails_when "a literal-seeded, parameter-and-literal-seeded or
time-seeded generator, a module-level random call, or an undeclared stream". Two
implementations of the words: W-alias resolves import aliases (import random as rnd; from
random import Random as R; from random import randint) and is the semantic reading;
W-attr matches only the literal attribute forms random.Random(...) and random.<fn>(...).
Inputs: round 1's C8 snippets S1 to S7 copied exactly from VAL-20261002-3b6a02
computations C8; the revision's restated S4 to S6; further forms. Snippets are parsed, never run.
"""
import ast, json
OK_NAMES = {"rng_seed"}; OK_CALLS = {"stream_for_label", "stream", "seeds.stream"}
RANDOM_FUNCS = {"random", "randint", "randrange", "getrandbits", "choice", "choices", "shuffle", "sample", "seed", "uniform", "randbytes", "binomialvariate", "gauss"}
def scan(src, mode):
    t = ast.parse(src); hits = []
    mod_alias, cls_alias, fn_alias = {"random"}, set(), set()
    if mode == "W-alias":
        for n in ast.walk(t):
            if isinstance(n, ast.Import):
                for a in n.names:
                    if a.name == "random": mod_alias.add(a.asname or "random")
            if isinstance(n, ast.ImportFrom) and n.module == "random":
                for a in n.names:
                    if a.name in ("Random", "SystemRandom"): cls_alias.add(a.asname or a.name)
                    elif a.name in RANDOM_FUNCS: fn_alias.add(a.asname or a.name)
    for n in ast.walk(t):
        if not isinstance(n, ast.Call): continue
        f = ast.unparse(n.func)
        head, _, attr = f.rpartition(".")
        is_ctor = (head in mod_alias and attr in ("Random", "SystemRandom")) or f in cls_alias
        is_fn = (head in mod_alias and attr in RANDOM_FUNCS) or f in fn_alias
        if is_ctor:
            arg = n.args[0] if n.args else None
            good = (isinstance(arg, ast.Name) and arg.id in OK_NAMES) or (isinstance(arg, ast.Call) and ast.unparse(arg.func) in OK_CALLS)
            if not good: hits.append(ast.unparse(n))
        elif is_fn:
            hits.append(ast.unparse(n))
    return hits
SNIPS = {
  # round 1 C8, verbatim
  "R1-S1 AC-12 stated mutation": "import random\nr = random.Random(12345)\n",
  "R1-S2 F-10 shape (literal XOR variable)": "import random\ndef f(d):\n    rng = random.Random(0xC0FFEE ^ d)\n    return rng\n",
  "R1-S3 F-10 shape, local import, compound": "def g(d, f):\n    import random\n    rng = random.Random(0x70B731 ^ (d << 16) ^ len(f))\n    return rng\n",
  "R1-S4 alias import": "from random import Random as R\nr = R(7)\n",
  "R1-S5 module-level random call": "import random\nx = random.getrandbits(8)\n",
  "R1-S6 time-seeded": "import random, time\nr = random.Random(time.time_ns())\n",
  "R1-S7 conforming (must pass)": "import random\ndef count_roots(rng_seed):\n    rng = random.Random(rng_seed)\n    return rng\n",
  # the revision's restated S4 to S6 (AC-12 named_cases)
  "RV-S4 random.random()": "import random\nx = random.random()\n",
  "RV-S5 random.seed(time.time())": "import random, time\nrandom.seed(time.time())\n",
  "RV-S6 random.Random(os.urandom(8))": "import random, os\nr = random.Random(os.urandom(8))\n",
  # further forms
  "X1 module alias": "import random as rnd\nr = rnd.Random(5)\n",
  "X2 from-import function": "from random import randint\nx = randint(0, 9)\n",
  "X3 SystemRandom": "import random\nr = random.SystemRandom()\n",
  "X4 seeds.py stream (must pass)": "import random\nfrom r1.runner import seeds\nr = random.Random(seeds.stream('20260920|C5|np=11|d=3|field=F2'))\n",
}
for name, src in SNIPS.items():
    print(json.dumps({"snippet": name, "W_alias_hits": scan(src, "W-alias"), "W_attr_hits": scan(src, "W-attr"),
                      "must_pass": name.endswith("(must pass)")}, sort_keys=True))

