"""C12 (completion gate: every JRD1-owned acceptance check can fail). Models of AC-1, AC-13, AC-14,
AC-17, AC-18 and AC-30 (iii) as the revision words them, each run on a passing input and on the
check's own mutation. Synthetic values; the plans and bound files are only hashed or parsed.
"""
import ast, copy, hashlib, importlib.util, json, os, re, secrets, shutil, sys
import yaml
R = "/home/user/crypto-autoresearcher"; HERE = os.path.dirname(os.path.abspath(__file__))
rd = yaml.safe_load(open(os.path.join(HERE, "committed", "revision-design.yaml")))["revision_design"]
res = {}
# AC-13 (CC-1): twenty session-minted ids; none in the union of earlier plans' ids or the sixteen bound dirs
union = set()
for p in ("trial-plan.json", "trial-plan-v2.json", "trial-plan-run.json", "trial-plan-run2.json", "trial-plan-run3.json", "trial-plan-cont.json"):
    union |= {t["run_id"] for t in json.load(open(R + "/experiments/EXP-QSP-70b731/" + p))["trials"]}
fresh = ["RUN-QSP-%s" % secrets.token_hex(3) for _ in range(20)]
while set(fresh) & union or len(set(fresh)) < 20: fresh = ["RUN-QSP-%s" % secrets.token_hex(3) for _ in range(20)]
def ac13(ids, recorded):
    return ids == recorded and len(set(ids)) == 20 and all(re.fullmatch(r"RUN-QSP-[0-9a-f]{6}", i) for i in ids) and not (set(ids) & union)
mut = list(fresh); mut[5] = "RUN-QSP-cec70a"
res["AC-13"] = {"earlier_plan_run_id_union_size": len(union), "fresh_synthetic_ids_in_memory_only": ac13(fresh, fresh), "mutation RUN-QSP-cec70a": ac13(mut, mut)}
# AC-14 (CC-2): trial ids exactly the twenty of trial-plan.json
twenty = [t.get("trial_id") or t.get("id") for t in json.load(open(R + "/experiments/EXP-QSP-70b731/trial-plan.json"))["trials"]]
order = ["stage0-hand-gate", "stage1-toy-calibration", "stage5-controls"] + ["stage2-bandL-n%d" % k for k in range(3, 15)] + ["stage3-bridge-n22", "stage4-bandH-n33", "stage4-bandH-n44", "stage4-bandH-n66", "stage-compare-sealed"]
res["AC-14"] = {"design_order_equals_trial-plan.json_set": sorted(order) == sorted(twenty) and len(order) == 20,
                "mutation drop stage2-bandL-n3": sorted([t for t in order if t != "stage2-bandL-n3"]) == sorted(twenty)}
# AC-17 (CI-2, DR-14): bound digests; mutation appends one byte to a scratch copy
rc9 = {l.split()[1]: l.split()[0] for l in rd["session_computations"]["items"]["R-C9"]["output"]["hash_stdout"].splitlines() if len(l.split()) == 2 and len(l.split()[0]) == 64}
ok = all(hashlib.sha256(open(R + "/" + p, "rb").read()).hexdigest() == h for p, h in rc9.items() if not p.startswith("tools/"))
blob = open(R + "/experiments/EXP-QSP-70b731/implementation/driver.py", "rb").read() + b"\n"
res["AC-17"] = {"bound_paths_equal_R-C9 (tools excluded)": ok, "mutation one byte appended to a scratch copy equals R-C9": hashlib.sha256(blob).hexdigest() == rc9["experiments/EXP-QSP-70b731/implementation/driver.py"]}
# AC-18 (CI-5): compile under this interpreter and scan for listed 3.12-only APIs
API = re.compile(r"binomialvariate|itertools\.batched|math\.sumprod|typing\.override|os\.path\.splitroot|sys\.monitoring")
def ac18(src):
    try: compile(src, "x.py", "exec")
    except SyntaxError as e: return "FAIL SyntaxError under %s" % sys.version.split()[0]
    return "FAIL api %s" % API.findall(src) if API.search(src) else "pass"
res["AC-18"] = {"interpreter": sys.version.split()[0], "clean": ac18("import itertools\nx = list(itertools.islice(range(3), 2))\n"),
                "mutation itertools.batched": ac18("import itertools\nx = list(itertools.batched(range(4), 2))\n"),
                "mutation type statement": ac18("type X = int\n"), "mutation PEP 695": ac18("def f[T](x: T) -> T:\n    return x\n")}
# AC-30 (iii): every WO item has a tq3 field containing "is a TQ-3 event"; mutation deletes one
items = rd["work_orders"]["WO-I"]["items"] + rd["work_orders"]["WO-R"]["items"]
def ac30iii(its): return all("is a TQ-3 event" in (i.get("tq3") or "") for i in its)
mut = copy.deepcopy(items); del mut[7]["tq3"]
res["AC-30 (iii)"] = {"design": ac30iii(items), "mutation one tq3 deleted": ac30iii(mut)}
# AC-1 field clause (D-1) on round-1 A4 and A5 shapes: check_run passes them, the WO-R-2 field clause fails them
WO_R2 = ["id", "experiment_id", "trial_id", "status", "plan", "code", "environment", "inference", "inputs", "timing", "result"]
def ac1_fields(body): return [k for k in WO_R2 if k not in body or body[k] in (None, "", {})]
base = {k: {"x": 1} for k in WO_R2}; base.update({"id": "RUN-SYNTH-1", "experiment_id": "EXP-SYNTH", "trial_id": "t", "status": "completed"})
a4 = dict(base); del a4["inference"]; a5 = dict(base); a5["environment"] = {}
res["AC-1 field clause"] = {"conforming": ac1_fields(base), "A4 inference absent": ac1_fields(a4), "A5 environment empty": ac1_fields(a5)}
print(json.dumps(res, indent=1, sort_keys=True))

